    @Before public void keys(){OwnerDataArchiveFixture.installFixtureVault();}
    @After public void clear(){OwnerDataArchiveFixture.removeFixtureVault();}
    private static String phase(OwnerDataArchiveFixture host,OwnerDataArchives archive,OwnerDataArchives.Selection selected,String section,String projects)throws Exception{
        String sha=selected.metadata().getString("archiveSha256");var confirmed=archive.review(selected,section,host.host.ownerArchiveProjectMapForOwner(projects,sha),new RunControl()).confirm();String action=confirmed.actionId();host.host.submitOwnerArchivePhaseForOwner(confirmed);long deadline=System.nanoTime()+10_000_000_000L;JSONObject actual;
        do{actual=host.tasks.ownerArchivePhaseForOwner(action);if(!"running".equals(actual.getString("status")))break;Thread.sleep(10);}while(System.nanoTime()<deadline);
        assertEquals(actual.toString(),"completed",actual.getString("status"));assertFalse(host.tasks.hasUnresolved(action));do{actual=host.host.queryOwnerArchivePhaseForOwner(action,new RunControl());if(!actual.has("observation"))break;Thread.sleep(5);}while(System.nanoTime()<deadline);assertTrue(actual.toString(),actual.optBoolean("found"));return action;
    }
    @Test public void mountedSelectedExportCrossInstallRestoresOnlyItsNewProjectAndPassiveDataThenColdQueriesOriginalPhases()throws Exception{
        byte[] zip;String original;try(var source=new ProjectMemoryArchiveNativeTest.Fixture(true)){
            original=source.project;String other=source.nativeHost.workspace.handle("create",new JSONObject().put("name","不在范围的另一个项目")).getString("id");source.nativeHost.workspace.handle("write",new JSONObject().put("projectId",other).put("path","secret.txt").put("expectedVersion",0).put("content","UNSELECTED_PROJECT_BYTES_418"));source.nativeHost.local.handle("prepare",new JSONObject().put("projectId",other));source.capture();JSONObject preview=source.archives.preview(source.packageSelection,new RunControl());assertEquals(1,preview.getJSONObject("review").getJSONObject("projects").getInt("projects"));assertEquals("project_only",preview.getJSONObject("review").getJSONObject("memory").getString("scopeMode"));ByteArrayOutputStream bytes=new ByteArrayOutputStream();source.archives.export(source.packageSelection,bytes,new RunControl());zip=bytes.toByteArray();
        }
        Path install=Files.createTempDirectory("mounted-project-memory-target-");String projectPhase,memoryPhase,target;
        try(var host=new OwnerDataArchiveFixture(RuntimeEnvironment.getApplication(),install,true)){
            var archive=host.host.ownerDataArchives(host.android);var selected=archive.read(new ByteArrayInputStream(zip),new RunControl());assertEquals(0,host.workspace.snapshot().getJSONArray("projects").length());assertThrows(UnsupportedOperationException.class,()->archive.review(selected,"memory",host.host.ownerArchiveProjectMapForOwner("",selected.metadata().getString("archiveSha256")),new RunControl()));
            projectPhase=phase(host,archive,selected,"projects","");JSONObject result=host.host.queryOwnerArchivePhaseForOwner(projectPhase,new RunControl());target=result.getJSONObject("projectMap").getString(original);assertNotEquals(original,target);assertEquals(1,host.workspace.snapshot().getJSONArray("projects").length());assertEquals(1,host.workspace.handle("list",new JSONObject().put("projectId",target)).getJSONArray("files").length());memoryPhase=phase(host,archive,selected,"memory",projectPhase);JSONObject actual=host.host.queryOwnerArchivePhaseForOwner(memoryPhase,new RunControl()).getJSONObject("nativeResult");assertFalse(actual.getBoolean("readGrantIssued"));assertFalse(actual.getBoolean("consentRestored"));assertEquals(0,actual.getInt("formalMemoryActivated"));assertTrue(actual.getInt("currentlyReadableRecords")>0);assertEquals(0,host.memory.handle("list",new JSONObject()).getJSONArray("records").length());
        }
        try(var host=new OwnerDataArchiveFixture(RuntimeEnvironment.getApplication(),install,true)){
            host.host.ownerDataArchives(host.android);assertTrue(host.host.queryOwnerArchivePhaseForOwner(projectPhase,new RunControl()).getBoolean("found"));assertTrue(host.host.queryOwnerArchivePhaseForOwner(memoryPhase,new RunControl()).getBoolean("found"));assertEquals(1,host.workspace.snapshot().getJSONArray("projects").length());var spaces=new NativeOwnerWorkflows(host.host,host.context,host.tasks,host.sources).projectMemoryForOwner();JSONArray choices=spaces.choicesForOwner();JSONObject row=choices.getJSONObject(0);var selected=spaces.selectForOwner(row.getString("checkoutId"),target,row.getString("revision"));JSONObject records=spaces.handleForOwner(selected,"list",new JSONObject());assertTrue(records.toString().contains("PROJECT_ARCHIVE_NATIVE_ORIGINAL_916"));assertFalse(records.toString().contains("UNSELECTED_PROJECT_BYTES_418"));assertFalse(records.toString().contains("OWNER_GLOBAL_NOT_IN_PROJECT_PACKAGE_271"));assertEquals(0,spaces.captureTaskConsentForOwner(selected).metadata().getJSONArray("selectedRecords").length());
        }
    }
    @Test public void mountedOriginalNamespaceForgetBeforeAndAfterOriginalNativeRestoreCannotBeWashedByNewProjectIds()throws Exception{try(var f=new ProjectMemoryArchiveNativeTest.Fixture(true)){
        f.capture();String projectPhase=phase(f.nativeHost,f.archives,f.packageSelection,"projects","");String memoryPhase=phase(f.nativeHost,f.archives,f.packageSelection,"memory",projectPhase);assertTrue(f.nativeHost.host.queryOwnerArchivePhaseForOwner(memoryPhase,new RunControl()).getJSONObject("nativeResult").getInt("currentlyReadableRecords")>0);f.forgetOriginal();assertEquals(0,f.nativeHost.host.queryOwnerArchivePhaseForOwner(memoryPhase,new RunControl()).getJSONObject("nativeResult").getInt("currentlyReadableRecords"));String laterProjects=phase(f.nativeHost,f.archives,f.packageSelection,"projects","");String laterMemory=phase(f.nativeHost,f.archives,f.packageSelection,"memory",laterProjects);assertEquals(0,f.nativeHost.host.queryOwnerArchivePhaseForOwner(laterMemory,new RunControl()).getJSONObject("nativeResult").getInt("currentlyReadableRecords"));assertEquals(1,f.nativeHost.memory.handle("list",new JSONObject()).getJSONArray("records").length());
    }}
    private static byte[] portable(OwnerDataArchives archive,OwnerDataArchives.Selection selected)throws Exception{ByteArrayOutputStream bytes=new ByteArrayOutputStream();archive.export(selected,bytes,new RunControl());return bytes.toByteArray();}
    private static String mapped(OwnerDataArchiveFixture host,OwnerDataArchives.Selection selected,String phase,String source)throws Exception{return host.host.ownerArchiveProjectMapForOwner(phase,selected.metadata().getString("archiveSha256")).forArchive(selected.metadata().getString("archiveSha256")).getString(source);}
    @Test public void carriedOriginalNamespaceForgetSurvivesAnotherProjectPlacementReexportAndFreshInstall()throws Exception{
        byte[] oldPackage,barrierPackage,reexported;String original,barrierOrigin;
        try(var f=new ProjectMemoryArchiveNativeTest.Fixture(true)){
            original=f.project;f.capture();oldPackage=portable(f.archives,f.packageSelection);f.forgetOriginal();String projects=phase(f.nativeHost,f.archives,f.packageSelection,"projects","");phase(f.nativeHost,f.archives,f.packageSelection,"memory",projects);barrierOrigin=mapped(f.nativeHost,f.packageSelection,projects,original);f.selected=f.choose(barrierOrigin);assertTrue(f.scopes.archiveForOwner(f.selected).getJSONArray("namespaceSourceFences").length()>0);f.capture();barrierPackage=portable(f.archives,f.packageSelection);
        }
        try(var host=new OwnerDataArchiveFixture(RuntimeEnvironment.getApplication(),Files.createTempDirectory("carried-project-barrier-middle-"),true)){
            var archive=host.host.ownerDataArchives(host.android);var negative=archive.read(new ByteArrayInputStream(barrierPackage),new RunControl());String negativeProjects=phase(host,archive,negative,"projects","");phase(host,archive,negative,"memory",negativeProjects);var old=archive.read(new ByteArrayInputStream(oldPackage),new RunControl());String projects=phase(host,archive,old,"projects","");String memory=phase(host,archive,old,"memory",projects);assertEquals(0,host.host.queryOwnerArchivePhaseForOwner(memory,new RunControl()).getJSONObject("nativeResult").getInt("currentlyReadableRecords"));String target=mapped(host,old,projects,original);var spaces=new NativeOwnerWorkflows(host.host,host.context,host.tasks,host.sources).projectMemoryForOwner();JSONArray choices=spaces.choicesForOwner();JSONObject choice=null;for(int n=0;n<choices.length();n++)if(target.equals(choices.getJSONObject(n).getString("projectId")))choice=choices.getJSONObject(n);assertNotNull(choice);var selected=spaces.selectForOwner(choice.getString("checkoutId"),target,choice.getString("revision"));reexported=portable(archive,archive.createProjectMemory(selected,new RunControl()));
        }
        try(var host=new OwnerDataArchiveFixture(RuntimeEnvironment.getApplication(),Files.createTempDirectory("carried-project-barrier-final-"),true)){
            var archive=host.host.ownerDataArchives(host.android);var prior=archive.read(new ByteArrayInputStream(reexported),new RunControl());String projects=phase(host,archive,prior,"projects","");phase(host,archive,prior,"memory",projects);var old=archive.read(new ByteArrayInputStream(oldPackage),new RunControl());String oldProjects=phase(host,archive,old,"projects","");String memory=phase(host,archive,old,"memory",oldProjects);assertEquals("same original SourceRef/namespace must retain its validated forget floor across another remap/export",0,host.host.queryOwnerArchivePhaseForOwner(memory,new RunControl()).getJSONObject("nativeResult").getInt("currentlyReadableRecords"));assertEquals(0,host.memory.handle("list",new JSONObject()).getJSONArray("records").length());
        }
    }
    @Test public void carriedOwnerPrivateSourceFloorIsReexportedWithoutAnyOwnerPrivateBodyOrGrant()throws Exception{
        byte[] oldPackage,negativePackage,reexported;String original;
        try(var f=new ProjectMemoryArchiveNativeTest.Fixture(true)){
            original=f.project;f.capture();oldPackage=portable(f.archives,f.packageSelection);JSONObject global=f.nativeHost.memory.handle("save",new JSONObject().put("record",new JSONObject().put("text","原全局同来源撤回标记").put("sourceRefs",f.formal.getJSONArray("sourceRefs")))).getJSONObject("record");f.nativeHost.memory.handle("forget",new JSONObject().put("scope",new JSONObject().put("ownerId","owner").put("spaceId","private")).put("id",global.getString("id")));negativePackage=portable(f.archives,f.archives.create(Set.of("memory"),new RunControl()));
        }
        try(var host=new OwnerDataArchiveFixture(RuntimeEnvironment.getApplication(),Files.createTempDirectory("private-source-floor-middle-"),true)){
            var archive=host.host.ownerDataArchives(host.android);var negative=archive.read(new ByteArrayInputStream(negativePackage),new RunControl());phase(host,archive,negative,"memory","");var old=archive.read(new ByteArrayInputStream(oldPackage),new RunControl());String projects=phase(host,archive,old,"projects","");String memory=phase(host,archive,old,"memory",projects);assertEquals(0,host.host.queryOwnerArchivePhaseForOwner(memory,new RunControl()).getJSONObject("nativeResult").getInt("currentlyReadableRecords"));String target=mapped(host,old,projects,original);var spaces=new NativeOwnerWorkflows(host.host,host.context,host.tasks,host.sources).projectMemoryForOwner();JSONObject choice=null;JSONArray choices=spaces.choicesForOwner();for(int n=0;n<choices.length();n++)if(target.equals(choices.getJSONObject(n).getString("projectId")))choice=choices.getJSONObject(n);assertNotNull(choice);var selected=spaces.selectForOwner(choice.getString("checkoutId"),target,choice.getString("revision"));JSONObject data=spaces.archiveForOwner(selected);assertFalse(data.toString().contains("OWNER_GLOBAL_NOT_IN_PROJECT_PACKAGE_271"));reexported=portable(archive,archive.createProjectMemory(selected,new RunControl()));
        }
        try(var host=new OwnerDataArchiveFixture(RuntimeEnvironment.getApplication(),Files.createTempDirectory("private-source-floor-final-"),true)){
            var archive=host.host.ownerDataArchives(host.android);var prior=archive.read(new ByteArrayInputStream(reexported),new RunControl());String projects=phase(host,archive,prior,"projects","");phase(host,archive,prior,"memory",projects);var old=archive.read(new ByteArrayInputStream(oldPackage),new RunControl());String oldProjects=phase(host,archive,old,"projects","");String memory=phase(host,archive,old,"memory",oldProjects);assertEquals("known original source floor must survive without copying its unrelated private receipt/body",0,host.host.queryOwnerArchivePhaseForOwner(memory,new RunControl()).getJSONObject("nativeResult").getInt("currentlyReadableRecords"));assertEquals(0,host.memory.handle("list",new JSONObject()).getJSONArray("records").length());
        }
    }
    @Test public void carriedExactRecordTombstoneKeepsItsRetainedAncestorBodyAcrossAnotherRemapAndReexport()throws Exception{
        byte[] oldPackage,negativePackage,reexported;String original;String ancestor="仍保留的原始祖先理由_671",forgotten="已经遗忘的派生结论_982";
        try(var f=new ProjectMemoryArchiveNativeTest.Fixture(true)){
            original=f.project;JSONObject parent=f.scopes.handleForOwner(f.selected,"save",new JSONObject().put("record",new JSONObject().put("text",ancestor))).getJSONObject("record");JSONObject child=f.scopes.handleForOwner(f.selected,"save",new JSONObject().put("record",new JSONObject().put("text",forgotten).put("sourceIds",new JSONArray().put(parent.getString("id"))))).getJSONObject("record");f.capture();oldPackage=portable(f.archives,f.packageSelection);f.scopes.handleForOwner(f.selected,"forgetReviewed",new JSONObject().put("id",child.getString("id")).put("expectedRevision",child.getLong("revision")));assertTrue(f.scopes.handleForOwner(f.selected,"list",new JSONObject()).toString().contains(ancestor));f.capture();negativePackage=portable(f.archives,f.packageSelection);
        }
        try(var host=new OwnerDataArchiveFixture(RuntimeEnvironment.getApplication(),Files.createTempDirectory("record-floor-middle-"),true)){
            var archive=host.host.ownerDataArchives(host.android);var negative=archive.read(new ByteArrayInputStream(negativePackage),new RunControl());String negativeProjects=phase(host,archive,negative,"projects","");phase(host,archive,negative,"memory",negativeProjects);var old=archive.read(new ByteArrayInputStream(oldPackage),new RunControl());String projects=phase(host,archive,old,"projects","");String memory=phase(host,archive,old,"memory",projects);assertEquals(3,host.host.queryOwnerArchivePhaseForOwner(memory,new RunControl()).getJSONObject("nativeResult").getInt("currentlyReadableRecords"));String target=mapped(host,old,projects,original);var spaces=new NativeOwnerWorkflows(host.host,host.context,host.tasks,host.sources).projectMemoryForOwner();JSONObject choice=null;JSONArray choices=spaces.choicesForOwner();for(int n=0;n<choices.length();n++)if(target.equals(choices.getJSONObject(n).getString("projectId")))choice=choices.getJSONObject(n);assertNotNull(choice);var selected=spaces.selectForOwner(choice.getString("checkoutId"),target,choice.getString("revision"));reexported=portable(archive,archive.createProjectMemory(selected,new RunControl()));
        }
        try(var host=new OwnerDataArchiveFixture(RuntimeEnvironment.getApplication(),Files.createTempDirectory("record-floor-final-"),true)){
            var archive=host.host.ownerDataArchives(host.android);var prior=archive.read(new ByteArrayInputStream(reexported),new RunControl());String projects=phase(host,archive,prior,"projects","");phase(host,archive,prior,"memory",projects);var old=archive.read(new ByteArrayInputStream(oldPackage),new RunControl());String oldProjects=phase(host,archive,old,"projects","");String memory=phase(host,archive,old,"memory",oldProjects);assertEquals("self tombstone is not permission to erase the still-retained ancestor",3,host.host.queryOwnerArchivePhaseForOwner(memory,new RunControl()).getJSONObject("nativeResult").getInt("currentlyReadableRecords"));String target=mapped(host,old,oldProjects,original);var spaces=new NativeOwnerWorkflows(host.host,host.context,host.tasks,host.sources).projectMemoryForOwner();JSONObject choice=null;JSONArray choices=spaces.choicesForOwner();for(int n=0;n<choices.length();n++)if(target.equals(choices.getJSONObject(n).getString("projectId")))choice=choices.getJSONObject(n);assertNotNull(choice);var selected=spaces.selectForOwner(choice.getString("checkoutId"),target,choice.getString("revision"));String data=spaces.handleForOwner(selected,"list",new JSONObject()).toString();assertTrue(data.contains(ancestor));assertFalse(data.contains(forgotten));
        }
    }
    @Test public void originalOwnerPrivateExportStaysSeparateAndForeignOrClearedProjectSelectionsCannotExport()throws Exception{try(var f=new ProjectMemoryArchiveNativeTest.Fixture(true);var foreign=new ProjectMemoryArchiveNativeTest.Fixture(true)){
        var privateOnly=f.archives.create(Set.of("memory"),new RunControl());JSONObject preview=f.archives.preview(privateOnly,new RunControl());assertFalse(preview.getJSONObject("review").has("projects"));var review=f.archives.review(privateOnly,"memory",f.nativeHost.host.ownerArchiveProjectMapForOwner("",privateOnly.metadata().getString("archiveSha256")),new RunControl());assertEquals("owner_private",review.metadata().getJSONObject("nativeScope").getString("scopeMode"));String original=phase(f.nativeHost,f.archives,privateOnly,"memory","");assertEquals(1,f.nativeHost.host.queryOwnerArchivePhaseForOwner(original,new RunControl()).getJSONObject("nativeResult").getInt("currentlyReadableRecords"));assertEquals(2,f.nativeHost.memory.handle("list",new JSONObject()).getJSONArray("records").length());assertThrows(SecurityException.class,()->f.archives.createProjectMemory(foreign.selected,new RunControl()));f.scopes.clearForOwner();assertThrows(SecurityException.class,()->f.archives.createProjectMemory(f.selected,new RunControl()));
    }}
